382	     *  list order. */
383	    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
384	        String prefix = " sheet=" + sheetId + " by=" + user;
385	        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix
386	                + " name=" + figures.name() + " due-total=" + show(figures.dueTotal())));
387	    }
388	
389	    /** Record, once the change commits, a SCORE line of each person's score in a snapshot, in the list order. */
390	    public void recordScores(String sheetId, String user, Snapshot snapshot) {
391	        String prefix = " sheet=" + sheetId + " by=" + user;
392	        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SCORE" + prefix
393	                + " name=" + figures.name() + " score=" + figures.score().toPlainString()));
394	    }
395	
396	    /** Record, once the change commits, a ROLLUP line of every person's figures in the list order, then the
397	     *  TOTALS line, whether or not they moved. */
398	    public void recordAll(String sheetId, String user) {
399	        Snapshot now = take(sheetId);
400	        String prefix = " sheet=" + sheetId + " by=" + user;
401	        now.people().values().forEach(figures -> audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
402	                + " claimed=" + figures.claimed().toPlainString() + " due-total=" + show(figures.dueTotal())
403	                + " overdue-total=" + figures.overdueTotal().toPlainString()));
404	        audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + now.claimedTotal().toPlainString()
405	                + " due-total=" + now.dueTotal().toPlainString()
406	                + " overdue-total=" + now.overdueTotal().toPlainString());
407	        recordAlerts(sheetId, prefix, null, now);
408	    }
409	
410	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
411	    public void recordChanges(String sheetId, String user, Snapshot before) {
412	        Snapshot after = take(sheetId);
413	        String prefix = " sheet=" + sheetId + " by=" + user;
414	        after.people().forEach((id, now) -> {
415	            Figures was = before.people().get(id);
416	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
417	                    || !sameDue(was.dueTotal(), now.dueTotal())
418	                    || was.overdueTotal().compareTo(now.overdueTotal()) != 0) {
419	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
420	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
421	                        + " overdue-total=" + now.overdueTotal().toPlainString());
422	            }
423	        });
424	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
425	                || before.dueTotal().compareTo(after.dueTotal()) != 0
426	                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
427	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
428	                    + " due-total=" + after.dueTotal().toPlainString()
429	                    + " overdue-total=" + after.overdueTotal().toPlainString());
430	        }
431	        recordAlerts(sheetId, prefix, before, after);
432	    }
433	
434	    /** Record, once the change commits, an ALERT line for each person whose due-total went from at or below the
435	     *  sheet's alert threshold (or none, or new to the sheet) to above it, in the list order; none when the
436	     *  threshold is off. */
437	    private void recordAlerts(String sheetId, String prefix, Snapshot before, Snapshot after) {
438	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
439	        if (threshold == null) {
440	            return;
441	        }
442	        after.people().forEach((id, now) -> {
443	            Figures was = before == null ? null : before.people().get(id);
444	            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
445	                audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
446	            }
447	        });
448	    }
449	
450	    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
451	        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
452	    }
453	
454	    /** Whether a claim counts toward claimed: its status counts, it is not left out by its person's
455	     *  retirement (a hold leaves it in), and it is not deferred past the sheet's today. */
456	    private static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
457	        return claim.getStatus().counts() && !retiredOut(claim, person, today) && !claim.deferredOn(today);
458	    }
459	
460	    /** Whether a claim counted by the status it had at the end of a day, as its status log records it:
461	     *  its latest line dated on or before it; not when it was added after it. A claim with no log counts
462	     *  by its status now. */
463	    private static boolean countsAt(Claim claim, LocalDate day) {
464	        ClaimStatus status = statusAt(claim, day);
465	        return status != null && status.counts();
466	    }
467	
468	    /** The status a claim had at the end of a day, as its status log records it: its latest line dated on or
469	     *  before it; none when it was added after it. A claim with no log has its status now. */
470	    private static ClaimStatus statusAt(Claim claim, LocalDate day) {
471	        List<StatusChange> log = claim.getStatusLog();
472	        if (log.isEmpty()) {
473	            return claim.getStatus();
474	        }
475	        ClaimStatus status = null;
476	        for (StatusChange change : log) {
477	            if (!change.getOn().isAfter(day)) {
478	                status = change.getStatus();
479	            }
480	        }
481	        return status;
482	    }
483	
484	    /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus the grace days of its
485	     *  person's grade in force on its date before the sheet's today. */
486	    private static boolean overdue(Optional<Sheet> sheet, Claim claim, Person person, LocalDate today) {
487	        return claim.getStatus().isOpen() && !claim.deferredOn(today) && today != null && claim.getDueBy() != null
488	                && lateFrom(sheet, claim, person).isBefore(today);
489	    }
490	
491	    /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
492	     *  person's grade in force then. */
493	    public static LocalDate lateFrom(Optional<Sheet> sheet, Claim claim, Person person) {
494	        String grade = person == null ? null : person.gradeOn(claim.getDate());
495	        return sheet.map(s -> s.lateFrom(claim.getDueBy(), grade, claim.getDate())).orElse(claim.getDueBy());
496	    }
497	
498	    /** Whether a retirement leaves a claim out of claimed: it is OPEN or PENDING, bound by no statement, and
499	     *  its person's retirement date is reached on the sheet's today. */
500	    private static boolean retiredOut(Claim claim, Person person, LocalDate today) {
501	        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.retiredBy(today);
502	    }
503	
504	    /** Whether a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by no
505	     *  statement, and its person's retirement date is reached on the sheet's today. A hold no longer does:
506	     *  it only takes a person's cut out of the pools. */
507	    public static boolean heldOut(Claim claim, Person person, LocalDate today) {
508	        return retiredOut(claim, person, today);
509	    }
510	
511	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
512	     *  the sheet (half to even with no sheet). */
513	    public static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
514	        LocalDate on = roundingDate(claim, sheetClaims);
515	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
516	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
517	    }
518	
519	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
520	     *  corrects (the claim of the same person with that number), its own when that is not found. */
521	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
522	        if (!claim.isCorrection()) {
523	            return claim.getDate();
524	        }
525	        return sheetClaims.stream()
526	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
527	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
528	    }
529	
530	    /** A claim's due from its figure: at least the sheet's floor in force on its date, then its late charge,
531	     *  worked out on that floored figure, on top while it is OPEN or PENDING (only those go overdue). A settled claim's due is frozen (it
532	     *  already holds the charge and floor fixed when it was settled), as is a bound one's (its statement bound
533	     *  the due as shown then, charge and floor included); a correction has neither late charge nor floor, and a
534	     *  waived claim no late charge. */
535	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, Person person, BigDecimal figure) {
536	        if (claim.getSettledDue() != null || claim.isBound() || claim.isCorrection()) {
537	            return figure;
538	        }
539	        return sheet.map(s -> {
540	                    BigDecimal floored = s.floored(figure, claim.getDate());
541	                    return claim.getStatus().isOpen() && !claim.isWaived()
542	                            ? floored.add(s.lateCharge(floored, lateFrom(sheet, claim, person), claim.getDate())) : floored;
543	                })
544	                .orElse(figure);
545	    }
546	
547	    /** A person's due-total at most the sheet's cap. */
548	    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal) {
549	        return sheet.map(s -> s.capped(dueTotal)).orElse(dueTotal);
550	    }
551	
552	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
553	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
554	    }
555	
556	    private static String show(BigDecimal due) {
557	        return due == null ? "n/a" : due.toPlainString();
558	    }
559	
560	    /** The grade's rate in force on a date for a claim: as {@link #inForce(List, String, LocalDate)}, each rate
561	     *  as it applies to the claim (a forward-only rate not to a claim already on the sheet when it was saved,
562	     *  which keeps what applied to it). */
563	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date, Claim claim) {
564	        List<Rate> forClaim = new ArrayList<>();
565	        sheetRates.forEach(r -> r.forClaim(claim.getId()).ifPresent(forClaim::add));
566	        return inForce(forClaim, grade, date);
567	    }
568	
569	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
570	     *  when the date is after that rate's to-date. The rates may be a sheet's followed by its ancestors',
571	     *  nearest first: the first sheet, in that order, with a rate of the grade in force then gives it. */
572	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
573	        Set<String> sheetIds = new LinkedHashSet<>();
574	        sheetRates.forEach(r -> sheetIds.add(r.getSheetId()));
575	        for (String sheetId : sheetIds) {
576	            Optional<Rate> found = inForceOn(sheetRates, sheetId, grade, date);
577	            if (found.isPresent()) {
578	                return found;
579	            }
580	        }
581	        return Optional.empty();
582	    }
583	
584	    private static Optional<Rate> inForceOn(List<Rate> sheetRates, String sheetId, String grade, LocalDate date) {
585	        return sheetRates.stream()
586	                .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
587	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
588	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
589	                .filter(r -> r.coversThrough(date));
590	    }
591	}
