package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.officefloor.hq.app.history.AsOf;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.template.ClaimTemplate;
import net.officefloor.hq.app.template.ClaimTemplateService;
import net.officefloor.hq.app.template.TemplateRefusedException;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people's claims on a sheet. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it: the amount with two decimals, the date YYYY-MM-DD, no number unless settled (or numbered before that rule),
     *  the due fixed when it was settled (none while its due is live)
     *  who opened it (none while a draft), whether its person's last statement bound it and the figure
     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
     *  otherwise), its status log, oldest first, and the date it is deferred until (none when never deferred), its proofs count and how many of them are receipts and photos,
     *  the user whose editor is open on it (none while unlocked), and whether it was added while its period
     *  was soft-closed, and the last day it was reminded (none when never), and its external reference (none when
     *  not given), and its tags, sorted, and its comments, in the order written, and its lines, in the order added, and whether its late charge is waived, and whether it is held. */
    public record ClaimView(long id, long personId, String amount, String date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog, String deferredUntil,
            int proofs, int proofReceipts, int proofPhotos, String splitFrom, String lockedBy, boolean lateEntry,
            String remindedOn, String ref, List<String> tags, String voidReason,
            List<CommentLine> comments, Integer settleBatch, List<LineView> lines, boolean waived, boolean held) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy().toString(),
                    claim.getStatusLog().stream().map(StatusLine::of).toList(),
                    claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                    claim.getProofs(), claim.getProofs(ProofKind.RECEIPT), claim.getProofs(ProofKind.PHOTO),
                    claim.getSplitFrom(), claim.getLockedBy(),
                    claim.isLateEntry(),
                    claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getSettleBatch(),
                    claim.getLines().stream().map(LineView::of).toList(), claim.isWaived(), claim.isHeld());
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then (YYYY-MM-DD), and
     *  the due it had then, two decimals (none when n/a). */
    public record StatusLine(ClaimStatus status, String by, String on, String due) {

        static StatusLine of(StatusChange change) {
            return new StatusLine(change.getStatus(), change.getBy(), change.getOn().toString(),
                    change.getDue() == null ? null : change.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, the sheet's today then (YYYY-MM-DD), and its text. */
    public record CommentLine(String by, String on, String text) {

        static CommentLine of(ClaimComment comment) {
            return new CommentLine(comment.getBy(), comment.getOn().toString(), comment.getText());
        }
    }

    /** A line of a claim: its label, quantity and unit amount, two decimals. */
    public record LineView(String label, int qty, String unit) {

        static LineView of(ClaimLine line) {
            return new LineView(line.getLabel(), line.getQty(), line.getUnit().toPlainString());
        }
    }

    /** A claim's fields; a missing date takes the sheet's today, a missing note is empty. A negative
     *  amount (a correction) names the number of the claim it corrects. */
    public record ClaimRequest(
            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 220) String corrects,
            @Size(max = 200) String ref,
            @Size(max = 2000) String tags) {

        String noteOrEmpty() {
            return note == null ? "" : note.trim();
        }

        /** The external reference, trimmed; none when blank. */
        String refOrNone() {
            return ref == null || ref.isBlank() ? null : ref.trim();
        }

        /** The tags, comma separated: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
        List<String> tagList() {
            return tags == null ? List.of()
                    : Arrays.stream(tags.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT))
                            .filter(t -> !t.isEmpty()).distinct().sorted().toList();
        }

        /** The number a correction names, trimmed; none when blank. */
        String correctsOrNone() {
            return corrects == null || corrects.isBlank() ? null : corrects.trim();
        }
    }

    /** The quick-add bar's name and amount. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal amount) {
    }

    /** A delete or restore that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimDeleteException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> deleteRefused(ClaimDeleteException e) {
        return Map.of("message", e.getMessage());
    }

    /** A reminder that is not allowed is refused with the reason, for the screen to show. */
    /** Hold an OPEN or PENDING claim, or release it when held. */
    @PostMapping("/claims/{claimId}/hold")
    public ClaimView hold(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.toggleHold(sheetId.trim(), user.trim(), claimId));
    }

    /** A hold or release of a claim in any status but OPEN or PENDING is refused with the reason. */
    @ExceptionHandler(ClaimHoldException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> holdRefused(ClaimHoldException e) {
        return Map.of("message", e.getMessage());
    }

    @ExceptionHandler(ClaimRemindException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> remindRefused(ClaimRemindException e) {
        return Map.of("message", e.getMessage());
    }

    /** A waiver that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimWaiveException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> waiveRefused(ClaimWaiveException e) {
        return Map.of("message", e.getMessage());
    }

    /** An empty comment is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimCommentException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> commentRefused(ClaimCommentException e) {
        return Map.of("message", e.getMessage());
    }

    /** A claim line that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimLineException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> lineRefused(ClaimLineException e) {
        return Map.of("message", e.getMessage());
    }
}

